shapes.code:
trait Shape:
    def area(self) -> Int: ...
    def name(self) -> String: ...


@fieldwise_init
struct Rectangle(Shape):
    var width: Int
    var height: Int

    def area(self) -> Int:
        return self.width * self.height

    def name(self) -> String:
        return "Rectangle"


@fieldwise_init
struct Triangle(Shape):
    var base: Int
    var height: Int

    def area(self) -> Int:
        return self.base * self.height // 2

    def name(self) -> String:
        return "Triangle"


def describe(shape: Some[Shape]):
    print(shape.name() + ":", shape.area())


def main():
    describe(Rectangle(3, 4))
    describe(Triangle(10, 3))

signature.code:
def fib(n: Int) -> Int:
    return n if n < 2 else fib(n - 1) + fib(n - 2)


# [brackets] hold compile-time parameters; (parens) hold run-time arguments.
def dot[dt: DType, w: SIMDLength, //](a: SIMD[dt, w], b: SIMD[dt, w]) -> Scalar[dt]:
    return (a * b).reduce_add()  # one vector multiply, then a horizontal sum


def power[n: Int](x: SIMD[DType.float32, 4]) -> SIMD[DType.float32, 4]:
    var acc = SIMD[DType.float32, 4](1)
    comptime for _ in range(n):  # unrolled by the compiler: no loop at run time
        acc *= x
    return acc


def main():
    comptime F = fib(20)  # ordinary Mojo code, evaluated by the compiler
    var v = SIMD[DType.float32, 4](1, 2, 3, 4)
    print(power[3](v), dot(v, v))
    var w = SIMD[DType.int16, 8](1, 2, 3, 4, 5, 6, 7, 8)
    print(dot(w, w), F)  # the same dot(), specialised for 8 x int16
